insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_40_v1'
from (values
('127.241.d.1.A',3,'When the price of a popular sneaker rises sharply, buyers usually purchase fewer pairs. This reflects the principle of:','["demand", "inflation", "tariffs", "barter"]'::jsonb,0,'As price rises, quantity demanded generally falls.','original'),
('127.241.d.1.A',4,'A bakery finds that at $2 per muffin it sells 100, but at $3 it sells 60. If a flood destroys wheat crops and muffin costs rise, suppliers will most likely:','["ignore costs", "offer fewer muffins unless prices rise", "stop charging customers", "offer more muffins at lower prices"]'::jsonb,1,'Higher costs reduce supply at old prices.','original'),
('127.241.d.1.B',3,'A haircut and a pair of shoes are examples of which, respectively?','["two services", "a good and a service", "a service and a good", "two goods"]'::jsonb,2,'Services are actions; goods are physical items.','original'),
('127.241.d.1.B',4,'Which item below is a service rather than a good?','["A new laptop", "A bag of rice", "A bicycle", "A plumber repairing a leaking pipe"]'::jsonb,3,'A repair is work done for someone.','original'),
('127.241.d.1.C',3,'A company that makes cars, a store that sells them, and a bank that finances them represent which kinds of business?','["manufacturing, retail, and financial services", "only retail", "only agriculture", "only government"]'::jsonb,0,'Different businesses perform different functions.','original'),
('127.241.d.1.C',4,'A store that buys goods from producers and sells them to consumers is classified as:','["extractive", "retail", "manufacturing", "nonprofit only"]'::jsonb,1,'Retailers sell directly to consumers.','original'),
('127.241.d.1.D',3,'The owner of a small shop who keeps all profits and is personally responsible for all debts runs a:','["cooperative", "corporation", "sole proprietorship", "franchise"]'::jsonb,2,'Sole proprietors have unlimited liability.','original'),
('127.241.d.1.D',4,'Which form of ownership gives owners limited liability and sells shares of stock?','["general partnership", "sole proprietorship", "barter group", "corporation"]'::jsonb,3,'Corporations are separate legal entities.','original'),
('127.241.d.1.E',3,'In a typical company, the human resources department is responsible for:','["hiring and supporting employees", "manufacturing goods only", "printing money", "setting taxes"]'::jsonb,0,'HR handles recruitment and employee matters.','original'),
('127.241.d.1.E',4,'A company chart showing who reports to whom is called an:','["balance sheet", "organizational chart", "income statement", "price list"]'::jsonb,1,'Org charts show structure and reporting lines.','original'),
('127.241.d.1.F',3,'A report showing a company''s revenues and expenses over a period is the:','["pay stub", "bank statement", "income statement", "balance sheet"]'::jsonb,2,'Income statements show profit or loss.','original'),
('127.241.d.1.F',4,'A balance sheet is built on which equation?','["expenses = income", "assets = cash", "revenue = profit", "assets = liabilities + owner''s equity"]'::jsonb,3,'The accounting equation balances.','original'),
('127.241.d.1.G',3,'The pattern of expansion, peak, contraction, and trough in the economy is the:','["business cycle", "trade route", "supply chain", "tax cycle"]'::jsonb,0,'Economies move through phases.','original'),
('127.241.d.1.G',4,'During which phase of the business cycle do unemployment and spending typically fall the most?','["recovery", "recession", "expansion", "peak"]'::jsonb,1,'Contraction brings less spending and more layoffs.','original'),
('127.241.d.2.A',3,'A manager knowingly hides a defect in a product from customers. This is:','["legal in every case", "required by law", "an unethical business practice", "good marketing"]'::jsonb,2,'Concealing defects is dishonest.','original'),
('127.241.d.2.A',4,'Which action is an ethical business practice?','["Padding the expense report", "Copying a competitor''s secret recipe", "Overstating product claims", "Accurately labeling ingredients on a food product"]'::jsonb,3,'Honesty in labeling is ethical.','original'),
('127.241.d.2.B',3,'A choice can be legal yet still considered unethical. Which describes that case?','["A company legally dumps waste but knows it harms a neighborhood", "A company is audited", "A company breaks a law", "A company follows all laws and is fair"]'::jsonb,0,'Legal does not always mean ethical.','original'),
('127.241.d.2.B',4,'Ethical choices are guided by values, legal choices by laws, and moral choices by:','["market prices", "personal beliefs of right and wrong", "company slogans", "tax rates"]'::jsonb,1,'Morals are rooted in personal conviction.','original'),
('127.241.d.3.A',3,'An economy where tradition decides what to produce, such as a village that farms the way it always has, is a:','["command economy", "market economy", "traditional economy", "mixed economy"]'::jsonb,2,'Custom guides production.','original'),
('127.241.d.3.B',3,'Private ownership, profit motive, competition, and consumer choice describe the:','["tribal system", "command system", "barter system", "private enterprise system"]'::jsonb,3,'Private enterprise relies on markets.','original'),
('127.241.d.3.B',4,'In a private enterprise system, businesses succeed mainly by:','["meeting consumer needs at a profit", "fixing all prices", "avoiding customers", "following government orders"]'::jsonb,0,'Profit rewards good service.','original'),
('127.241.d.3.C',3,'If a company''s expenses are greater than its revenues, it has:','["a profit", "a loss", "a surplus", "a dividend"]'::jsonb,1,'Revenue minus expenses decides the result.','original'),
('127.241.d.3.C',4,'Which change would most directly increase a company''s profit?','["Hiring more staff with no new sales", "Raising rent without raising sales", "Lowering production costs while keeping sales steady", "Buying unused equipment"]'::jsonb,2,'Lower costs improve profit.','original'),
('127.241.d.4.A',3,'A company that sells products in many countries is participating in the:','["home market only", "local barter", "closed market", "global economy"]'::jsonb,3,'Business crosses borders.','original'),
('127.241.d.4.A',4,'One way global business affects society is by:','["creating jobs and offering more product choices", "stopping innovation", "removing competition", "ending all trade"]'::jsonb,0,'Global trade expands choices.','original'),
('127.241.d.4.B',3,'Trade within a country''s borders is:','["world trade", "domestic trade", "import trade", "embargo"]'::jsonb,1,'Domestic means within one nation.','original'),
('127.241.d.4.B',4,'Selling goods between two countries is an example of:','["domestic trade", "a barter fair", "world trade", "a local sale"]'::jsonb,2,'International trade crosses borders.','original'),
('127.241.d.4.C',3,'Goods that a country sells to other countries are called:','["quotas", "tariffs", "imports", "exports"]'::jsonb,3,'Exports leave the country.','original'),
('127.241.d.4.C',4,'If imports exceed exports, a country has a:','["trade deficit", "balanced budget", "trade surplus", "tax cut"]'::jsonb,0,'A deficit means more imports than exports.','original'),
('127.241.d.5.A',3,'A government that sets safety rules for food and drugs is acting as a:','["competitor", "regulator", "customer", "supplier"]'::jsonb,1,'Governments regulate for safety.','original'),
('127.241.d.5.A',4,'A government agency that buys paper and computers for its offices is acting as a:','["tax collector only", "competitor only", "consumer", "regulator only"]'::jsonb,2,'Governments also buy goods.','original'),
('127.241.d.5.B',3,'Collecting taxes and enforcing contracts are activities performed by:','["stock exchanges", "consumers only", "labor unions", "government"]'::jsonb,3,'Governments tax and enforce laws.','original'),
('127.241.d.5.B',4,'Which is an activity of government in business?','["Issuing licenses and enforcing antitrust laws", "Writing company mottos", "Choosing company colors", "Setting the weather"]'::jsonb,0,'Governments license and regulate competition.','original'),
('127.241.d.5.C',3,'Courts that settle disputes between a business and a customer are part of the:','["tax system", "legal system", "banking system", "trade system"]'::jsonb,1,'Courts resolve legal disputes.','original'),
('127.241.d.5.C',4,'A business signs a contract and the other party fails to pay. The business can seek relief through:','["a trade show", "a marketing plan", "the court system", "the weather service"]'::jsonb,2,'Courts enforce contracts.','original'),
('127.241.d.5.D',3,'An organization of workers that bargains with employers about wages and conditions is a:','["cooperative bank", "corporation", "trade tariff", "labor union"]'::jsonb,3,'Unions represent workers.','original'),
('127.241.d.5.D',4,'Collective bargaining is when:','["union representatives negotiate with an employer for all members", "a company sets prices", "courts print money", "one employee quits"]'::jsonb,0,'Bargaining is group negotiation.','original'),
('127.241.d.6.A',3,'Marketing a service like car repair usually relies more on:','["packaging", "reputation and trust", "shelf displays", "coupons only"]'::jsonb,1,'Services are intangible, so trust matters.','original'),
('127.241.d.6.A',4,'Which difference is most important when marketing goods versus services?','["Services are always free", "Goods cannot be priced", "Goods are tangible and can be displayed; services are intangible", "Goods have no customers"]'::jsonb,2,'Tangibility changes marketing.','original'),
('127.241.d.6.B',3,'A company that takes raw materials like iron ore from the earth is a:','["banker", "wholesaler", "retailer", "raw-goods producer"]'::jsonb,3,'Raw-goods producers extract resources.','original'),
('127.241.d.6.B',4,'A business that turns raw materials into finished goods is a:','["manufacturer", "retailer", "lender", "consumer"]'::jsonb,0,'Manufacturers make products from inputs.','original'),
('127.241.d.6.C',3,'A supermarket, a department store, and a convenience store are types of:','["wholesalers", "retailers", "manufacturers", "producers"]'::jsonb,1,'Retailers sell to the final consumer.','original'),
('127.241.d.6.C',4,'A business that sells only through a website is a:','["wholesaler", "raw-goods producer", "non-store retailer", "franchisor only"]'::jsonb,2,'Online sellers are non-store retailers.','original'),
('127.241.d.6.D',3,'Retailers help the private enterprise system by:','["making laws", "printing money", "setting taxes", "making goods available to consumers"]'::jsonb,3,'They link producers and consumers.','original'),
('127.241.d.6.D',4,'A retailer competes on price, selection, and service, which supports the principle of:','["competition", "central planning", "monopoly", "tradition"]'::jsonb,0,'Competition benefits consumers.','original'),
('127.241.d.6.E',3,'A business that buys large quantities from manufacturers and sells to retailers is a:','["bank", "wholesaler", "consumer", "producer"]'::jsonb,1,'Wholesalers sit between makers and stores.','original'),
('127.241.d.6.E',4,'A warehouse club selling bulk goods to store owners is an example of:','["an extractive business", "a government agency", "a wholesaler", "a raw-goods producer"]'::jsonb,2,'Bulk sales to resellers are wholesale.','original'),
('127.241.d.6.F',3,'Wholesalers help the economy by:','["setting tariffs", "making laws", "printing currency", "storing goods and delivering them to retailers"]'::jsonb,3,'They provide storage and distribution.','original'),
('127.241.d.6.F',4,'Without wholesalers, a small retailer might have to:','["buy from many individual manufacturers", "pay no taxes", "stop needing stock", "avoid all customers"]'::jsonb,0,'Wholesalers simplify purchasing.','original'),
('127.241.d.7.A',3,'Producing more output with the same resources is an increase in:','["debt", "productivity", "taxation", "inflation"]'::jsonb,1,'Productivity measures output per input.','original'),
('127.241.d.7.A',4,'A factory makes 600 widgets with 10 workers. Output per worker is:','["600", "6", "60", "10"]'::jsonb,2,'600 / 10 = 60.','original'),
('127.241.d.7.B',3,'Each worker on an assembly line doing one task is called:','["barter", "budgeting", "retailing", "division of labor"]'::jsonb,3,'Dividing tasks increases efficiency.','original'),
('127.241.d.7.B',4,'Specialization usually increases productivity because workers:','["become faster and more skilled at one task", "work fewer hours", "avoid teamwork", "stop learning"]'::jsonb,0,'Practice builds skill.','original'),
('127.241.d.7.C',3,'A union that negotiates for better pay is an example of organized labor interacting with:','["only farms", "business", "only schools", "only banks"]'::jsonb,1,'Unions bargain with employers.','original'),
('127.241.d.7.C',4,'A strike is:','["a tax payment", "a loan", "workers stopping work to press demands", "a merger"]'::jsonb,2,'Strikes are collective work stoppages.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_40_v1'
from (values
('127.241.d.8.A',3,'Paying for a purchase with plastic that draws money directly from your checking account is a:','["check on credit", "loan", "credit card", "debit card"]'::jsonb,3,'Debit pulls from your own funds.','original'),
('127.241.d.8.A',4,'Using a credit card means you are:','["borrowing money to be repaid later", "spending your own cash", "receiving a gift", "earning interest"]'::jsonb,0,'Credit is a loan.','original'),
('127.241.d.8.B',3,'Bills issued by a central bank, such as a $20 note, are:','["commodities", "paper money", "securities", "coins"]'::jsonb,1,'Banknotes are paper currency.','original'),
('127.241.d.8.B',4,'Which is a type of currency?','["warranties", "stocks", "coins", "coupons"]'::jsonb,2,'Coins are metal currency.','original'),
('127.241.d.8.C',3,'Using dollars to buy groceries shows money acting as a:','["tax", "store of debt", "price ceiling", "medium of exchange"]'::jsonb,3,'Money lets us trade easily.','original'),
('127.241.d.8.C',4,'Saving money for a future purchase shows money acting as a:','["store of value", "unit of barter", "unit of measure", "tariff"]'::jsonb,0,'Money holds value over time.','original'),
('127.241.d.8.D',3,'Credit allows a family to:','["avoid all fees", "buy now and pay later", "ignore payments", "earn interest on debt"]'::jsonb,1,'Credit extends purchasing power.','original'),
('127.241.d.8.D',4,'A good credit history helps a person:','["receive free items", "skip payments", "qualify for loans at lower interest rates", "avoid paying taxes"]'::jsonb,2,'Lenders reward reliability.','original'),
('127.241.d.8.E',3,'Writing a check when the account has insufficient funds can lead to:','["a refund", "a bonus", "extra interest earned", "fees and legal trouble"]'::jsonb,3,'Bouncing checks has consequences.','original'),
('127.241.d.8.E',4,'A person who signs a credit agreement is legally responsible for:','["repaying the amount owed under the terms", "only the interest", "nothing", "only the first payment"]'::jsonb,0,'Agreements are binding.','original'),
('127.241.d.9.A',3,'Providing accurate information on a loan application is important because false information can:','["raise interest earned", "result in legal penalties", "remove debt", "shorten the loan"]'::jsonb,1,'Misrepresentation is illegal.','original'),
('127.241.d.9.A',4,'Why must an employee give correct Social Security information on tax forms?','["to get a discount", "to avoid work", "to ensure wages and taxes are recorded properly", "to lower the price of goods"]'::jsonb,2,'Accurate records prevent errors.','original'),
('127.241.d.9.B',3,'An employee earns $800 and has $120 withheld. Net pay is:','["$120", "$920", "$800", "$680"]'::jsonb,3,'800 - 120 = 680.','original'),
('127.241.d.9.B',4,'A worker earns $15 per hour for 40 hours. Gross pay is:','["$600", "$150", "$400", "$55"]'::jsonb,0,'15 x 40 = 600.','original'),
('127.241.d.9.C',3,'A checking account is mainly used for:','["paying taxes only", "paying bills and daily purchases", "buying stocks", "long-term growth only"]'::jsonb,1,'Checking supports frequent transactions.','original'),
('127.241.d.9.C',4,'A savings account usually pays more than a checking account because it:','["charges no fees ever", "lets you overdraw", "earns interest on stored funds", "has no balance"]'::jsonb,2,'Savings accounts reward saving.','original'),
('127.241.d.9.D',4,'Your records show $500 but the bank statement shows $450 because a $50 check has not cleared. After reconciling you find:','["a bank error", "fraud", "a missing deposit", "the balances agree"]'::jsonb,3,'Outstanding checks explain the difference.','original'),
('127.241.d.9.E',3,'A bank that offers accounts only online usually has lower fees but no:','["physical branch", "interest", "accounts", "FDIC protection ever"]'::jsonb,0,'Online banks lack branches.','original'),
('127.241.d.9.E',4,'Which is a disadvantage of online banking?','["24-hour access", "difficulty depositing cash in person", "lower fees", "easy transfers"]'::jsonb,1,'Cash deposits can be harder.','original'),
('127.241.d.9.F',3,'Investing $1,000 at 5% simple interest for 2 years earns how much interest?','["$50", "$10", "$100", "$1,050"]'::jsonb,2,'1000 x 0.05 x 2 = 100.','original'),
('127.241.d.9.F',4,'The earlier a person starts investing, the more their money can grow through:','["depreciation", "inflation", "withholding", "compounding"]'::jsonb,3,'Interest earns interest over time.','original'),
('127.241.d.9.G',3,'The form most employees use to report yearly earnings and calculate tax owed is the:','["Form 1040", "bank statement", "W-4 only", "pay stub"]'::jsonb,0,'Form 1040 is the individual income tax return.','original'),
('127.241.d.9.G',4,'An employer gives an employee a W-2 to show:','["tariff rates", "wages earned and taxes withheld", "bank balances", "stock prices"]'::jsonb,1,'W-2 supports tax filing.','original'),
('127.241.d.10.A',3,'Creating, communicating, and delivering value to customers describes:','["accounting", "manufacturing only", "marketing", "banking"]'::jsonb,2,'Marketing connects products and customers.','original'),
('127.241.d.10.A',4,'Which statement best defines marketing?','["Setting tax rates", "Making products only", "Printing invoices", "The process of identifying and satisfying customer needs"]'::jsonb,3,'Marketing meets needs.','original'),
('127.241.d.10.B',3,'Marketing works with finance to decide:','["budgets for promotion", "court dates", "employee holidays", "tax law"]'::jsonb,0,'Marketing needs funding.','original'),
('127.241.d.10.B',4,'Marketing depends on production to ensure that:','["taxes are paid", "products meet customer expectations", "loans are closed", "bills are filed"]'::jsonb,1,'Quality affects sales.','original'),
('127.241.d.10.C',3,'The belief that a business succeeds by satisfying customer needs is the:','["tax code", "barter idea", "marketing concept", "production concept only"]'::jsonb,2,'Customer focus is central.','original'),
('127.241.d.10.C',4,'A company that surveys customers before designing a product is following the:','["sales quota", "budget concept", "cost concept", "marketing concept"]'::jsonb,3,'Research guides design.','original'),
('127.241.d.10.D',3,'Pricing, promotion, distribution, and market research are:','["marketing functions", "bank accounts", "union rules", "tax forms"]'::jsonb,0,'These are key marketing activities.','original'),
('127.241.d.10.D',4,'Getting products from a factory to stores is the marketing function of:','["promotion", "distribution", "selling", "pricing"]'::jsonb,1,'Distribution moves goods.','original'),
('127.241.d.11.A',3,'A market is a group of:','["only banks", "only producers", "people who want and can buy a product", "only sellers"]'::jsonb,2,'Markets consist of buyers.','original'),
('127.241.d.11.A',4,'Market identification helps a business:','["hire staff", "set taxes", "print money", "find who is likely to buy its product"]'::jsonb,3,'Knowing the market focuses effort.','original'),
('127.241.d.11.B',3,'Dividing buyers by age, income, or location creates:','["market segments", "supply chains", "business cycles", "tax brackets"]'::jsonb,0,'Segments group similar buyers.','original'),
('127.241.d.11.B',4,'Which is a segment based on geography?','["customers with high income", "customers in a particular city", "customers who like sports", "customers aged 20-30"]'::jsonb,1,'Location defines geographic segments.','original'),
('127.241.d.11.C',3,'Selling one product to everyone without tailoring is:','["segmentation", "direct sales", "mass marketing", "niche marketing"]'::jsonb,2,'Mass marketing targets all.','original'),
('127.241.d.11.C',4,'Unlike mass marketing, segmentation:','["uses no research", "ignores customers", "sells to everyone", "tailors the message to a specific group"]'::jsonb,3,'Segmentation focuses on a group.','original'),
('127.241.d.11.D',3,'The specific group of customers a business aims to serve is its:','["target market", "supply chain", "tax base", "labor pool"]'::jsonb,0,'Target markets guide strategy.','original'),
('127.241.d.11.D',4,'Targeting helps a business because it:','["stops competition", "uses limited resources on likely buyers", "removes risk entirely", "avoids profit"]'::jsonb,1,'Focus improves efficiency.','original'),
('127.241.d.11.E',3,'A company sells running shoes to teens who play sports. The target market is chosen using:','["court rulings", "tax records", "market segmentation", "random guess"]'::jsonb,2,'Segmentation identifies the target.','original'),
('127.241.d.11.E',4,'A shop selling baby clothes would most likely target:','["college athletes", "office managers", "retired travelers", "new parents"]'::jsonb,3,'The product fits their needs.','original'),
('127.241.d.12.A',3,'A plan that explains how a business will reach customers and meet goals is a:','["marketing strategy", "wage scale", "tax plan", "budget cut"]'::jsonb,0,'Strategies guide marketing.','original'),
('127.241.d.12.A',4,'A good marketing strategy begins with:','["buying equipment", "understanding customer needs", "hiring more staff", "raising prices"]'::jsonb,1,'Customer insight comes first.','original'),
('127.241.d.12.B',3,'Product, price, place, and promotion make up the:','["tax code", "balance sheet", "marketing mix", "supply chain"]'::jsonb,2,'These are the four Ps.','original'),
('127.241.d.12.B',4,'In the marketing mix, ''place'' refers to:','["what it looks like", "how it is advertised", "how much it costs", "where and how a product is distributed"]'::jsonb,3,'Place concerns distribution.','original'),
('127.241.d.12.C',3,'A company offering a quality product at a fair price, available in many stores, and advertised widely has:','["an effective marketing mix", "only a price", "no strategy", "a weak mix"]'::jsonb,0,'All four elements work together.','original'),
('127.241.d.12.C',4,'Which example shows a well-matched marketing mix?','["A product with no advertising", "A premium watch sold in luxury stores with high-end advertising", "A luxury watch sold at a flea market", "A low-cost item in luxury shops"]'::jsonb,1,'Elements should fit the target market.','original'),
('127.241.d.12.D',3,'A student designs a lemonade stand plan with a flavor, a price, a location, and a sign. She is creating:','["a tax return", "a balance sheet", "a marketing mix", "a union contract"]'::jsonb,2,'She has defined all four Ps.','original'),
('127.241.d.12.D',4,'When creating a marketing mix for a teen-focused app, the best promotion is likely:','["radio for seniors", "printed yellow pages", "newspaper classified ads", "social media ads"]'::jsonb,3,'Teens use social media.','original'),
('127.241.d.12.E',3,'Customers who give reviews and share posts show the role of:','["participation in marketing", "banking", "price fixing", "taxation"]'::jsonb,0,'Participation builds engagement.','original'),
('127.241.d.12.E',4,'A brand that asks customers to vote on new flavors uses participation to:','["reduce choices", "involve customers in product decisions", "avoid advertising", "raise taxes"]'::jsonb,1,'Involvement builds loyalty.','original'),
('127.241.d.13.A',3,'Listing what you enjoy doing and what you value helps you analyze your:','["tax rate", "credit limit", "goals and interests", "bank fees"]'::jsonb,2,'Self-analysis guides career choice.','original'),
('127.241.d.13.A',4,'A student who loves building things might explore careers in:','["only law", "only banking", "only retail", "construction or engineering"]'::jsonb,3,'Interests suggest careers.','original'),
('127.241.d.13.B',3,'Strong communication and math skills are examples of:','["talents, abilities, and skills", "tax forms", "loans", "stock prices"]'::jsonb,0,'Skills inform career fit.','original'),
('127.241.d.13.B',4,'Taking an interest or aptitude survey helps determine:','["your credit score", "your strengths for different careers", "your bank balance", "your tax bracket"]'::jsonb,1,'Assessments reveal strengths.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
