('127.243.d.10.C',3,'A loan secured by real estate is a:','["mortgage", "draft", "bailment", "lease"]'::jsonb,0,'Mortgages are secured by property.','original'),
('127.243.d.10.C',4,'A mortgage with an interest rate that stays the same for life is a:','["adjustable mortgage", "fixed-rate mortgage", "balloon lease", "variable warranty"]'::jsonb,1,'Fixed rates do not change.','original'),
('127.243.d.10.D',3,'The agreement allowing a tenant to use property for rent is a:','["warranty", "deed", "lease", "will"]'::jsonb,2,'Leases govern tenancy.','original'),
